  1→/**
  2→ * kakomon-generator CLIエントリポイント
  3→ *
  4→ * 処理フロー:
  5→ *   Phase 1+2a: detectQuestions — 問題PDF → Gemini で境界+座標を一括検出
  6→ *   Phase 2b:   splitProblems  — 検出結果 → 画像切り出し+PDF生成（Gemini不使用）
  7→ *   Phase 3:    tagQuestions   — 切り出し画像 → Gemini でトピック付け
  8→ *   Phase 4:    splitAnswers   — 解答PDF → Gemini で解答領域一括検出+切り出し
  9→ */
 10→
 11→import fs from "node:fs/promises";
 12→import path from "node:path";
 13→
 14→import { detectQuestions } from "./phases/detect.js";
 15→import { splitProblems } from "./phases/split.js";
 16→import { tagQuestions } from "./phases/tag.js";
 17→import { splitAnswers } from "./phases/answer.js";
 18→import {
 19→  uploadToR2,
 20→  originalPdfKey,
 21→  problemImageKey,
 22→  problemPdfKey,
 23→  answerPdfKey,
 24→  resolveSubjectKey,
 25→  resolveSubjectName,
 26→} from "./lib/r2.js";
 27→import {
 28→  upsertUniversity,
 29→  createDocument,
 30→  createQuestion,
 31→} from "./lib/supabase.js";
 32→import type {
 33→  AnswerSplitResult,
 34→  DetectedQuestion,
 35→  QuestionBoundary,
 36→  CliOptions,
 37→} from "./types.js";
 38→
 39→/**
 40→ * DetectedQuestion[] から QuestionBoundary[] に変換する
 41→ * Phase 4 (splitAnswers) が従来の QuestionBoundary 形式を必要とするため
 42→ */
 43→function toBoundaries(detected: DetectedQuestion[]): QuestionBoundary[] {
 44→  return detected.map((q) => {
 45→    const pages = q.regions.map((r) => r.page);
 46→    return {
 47→      label: q.label,
 48→      startPage: Math.min(...pages),
 49→      endPage: Math.max(...pages),
 50→    };
 51→  });
 52→}
 53→
 54→async function main(options: CliOptions): Promise<void> {
 55→  const outDir = options.outDir;
 56→  if (outDir) {
 57→    await fs.mkdir(outDir, { recursive: true });
 58→  }
 59→
 60→  // PDF読み込み
 61→  const problemPdf = Buffer.from(await fs.readFile(options.problem));
 62→  const answerPdf = options.answer
 63→    ? Buffer.from(await fs.readFile(options.answer))
 64→    : undefined;
 65→
 66→  console.log(`問題PDF: ${options.problem} (${(problemPdf.length / 1024).toFixed(0)} KB)`);
 67→  if (answerPdf) {
 68→    console.log(`解答PDF: ${options.answer} (${(answerPdf.length / 1024).toFixed(0)} KB)`);
 69→  } else {
 70→    console.log("解答PDF: なし（スキップ）");
 71→  }
 72→  console.log(`科目: ${options.subject}  大学: ${options.university}  年度: ${options.year}`);
 73→  console.log("");
 74→
 75→  // Phase 1+2a: 境界検出+座標の一括取得（1回のGemini API呼び出し）
 76→  console.log("-- Phase 1: 境界検出+座標取得 ---------------------");
 77→  const detectedQuestions = await detectQuestions(problemPdf);
 78→  console.log(`  検出された大問: ${detectedQuestions.length}件\n`);
 79→
 80→  // Phase 2b: 問題の切り出し（Gemini不使用、画像処理のみ）
 81→  console.log("-- Phase 2: 問題切り出し -------------------------");
 82→  const splitResults = await splitProblems(problemPdf, detectedQuestions);
 83→  console.log(`  切り出し完了: ${splitResults.length}件\n`);
 84→
 85→  // Phase 3: トピック付け（切り出し画像 → Gemini Vision）
 86→  console.log("-- Phase 3: トピック付け -------------------------");
 87→  const subjectName = resolveSubjectName(options.subject);
 88→  const tagResults = await tagQuestions(splitResults, subjectName);
 89→  console.log(`  タグ付け完了: ${tagResults.length}件\n`);
 90→
 91→  // Phase 4: 解答の切り出し（解答PDFがある場合のみ）
 92→  const boundaries = toBoundaries(detectedQuestions);
 93→  let answerResults: AnswerSplitResult[] = [];
 94→  if (answerPdf) {
 95→    console.log("-- Phase 4: 解答切り出し -------------------------");
 96→    answerResults = await splitAnswers(answerPdf, boundaries);
 97→    console.log(`  切り出し完了: ${answerResults.length}件\n`);
 98→  } else {
 99→    console.log("-- Phase 4: 解答切り出し（スキップ: 解答PDFなし） --\n");
100→  }
101→
102→  // ローカル出力（--out-dir 指定時のみ）
103→  if (outDir) {
104→    console.log("-- ローカル出力 ----------------------------------");
105→    for (const split of splitResults) {
106→      const baseName = `${options.year}_${options.examType}_${options.subject}_Q${split.questionNumber}`;
107→      const imgPath = path.join(outDir, `${baseName}.png`);
108→      const pdfPath = path.join(outDir, `${baseName}.pdf`);
109→
110→      await fs.writeFile(imgPath, split.imagePng);
111→      await fs.writeFile(pdfPath, split.pdfBuffer);
112→      console.log(`  ${split.label}: ${imgPath}, ${pdfPath}`);
113→    }
114→
115→    if (answerResults.length > 0) {
116→      for (const ans of answerResults) {
117→        const baseName = `${options.year}_${options.examType}_${options.subject}_A${ans.questionNumber}`;
118→        const pdfPath = path.join(outDir, `${baseName}.pdf`);
119→
120→        await fs.writeFile(pdfPath, ans.pdfBuffer);
121→        console.log(`  ${ans.label} 解答: ${pdfPath}`);
122→      }
123→    }
124→
125→    const tagsJson = tagResults.map((t) => ({
126→      label: t.label,
127→      questionNumber: t.questionNumber,
128→      topicTags: t.topicTags,
129→    }));
130→    const tagsPath = path.join(outDir, "tags.json");
131→    await fs.writeFile(tagsPath, JSON.stringify(tagsJson, null, 2));
132→    console.log(`  タグ: ${tagsPath}\n`);
133→  }
134→
135→  // Phase 5: R2アップロード + Supabase DB書き込み
136→  console.log("-- Phase 5: R2アップロード + DB書き込み ------------");
137→
138→  const { university, year, subject, examType } = options;
139→
140→  // 大学ID・科目キーをASCIIに解決、DB用は日本語名に解決
141→  const universityId = await upsertUniversity(university);
142→  const subjectKey = resolveSubjectKey(subject);
143→  const subjectJa = resolveSubjectName(subject);
144→  console.log(`  大学ID: ${universityId}, 科目キー: ${subjectKey}`);
145→
146→  // オリジナルPDFをR2にアップロード
147→  const problemOrigKey = originalPdfKey(universityId, year, subjectKey, examType, "problem");
148→  const uploadPromises: Promise<unknown>[] = [uploadToR2(problemOrigKey, problemPdf, "application/pdf")];
149→  console.log(`  R2: ${problemOrigKey}`);
150→
151→  let answerOrigKey: string | undefined;
152→  if (answerPdf) {
153→    answerOrigKey = originalPdfKey(universityId, year, subjectKey, examType, "answer");
154→    uploadPromises.push(uploadToR2(answerOrigKey, answerPdf, "application/pdf"));
155→    console.log(`  R2: ${answerOrigKey}`);
156→  }
157→  await Promise.all(uploadPromises);
158→
159→  // 大問ごとのファイルをR2にアップロード
160→  for (const split of splitResults) {
161→    const qn = split.questionNumber;
162→    const imgKey = problemImageKey(universityId, year, subjectKey, examType, qn);
163→    const pdfKey = problemPdfKey(universityId, year, subjectKey, examType, qn);
164→    await Promise.all([
165→      uploadToR2(imgKey, split.imagePng, "image/png"),
166→      uploadToR2(pdfKey, split.pdfBuffer, "application/pdf"),
167→    ]);
168→    console.log(`  R2: ${imgKey}, ${pdfKey}`);
169→  }
170→
171→  if (answerResults.length > 0) {
172→    for (const ans of answerResults) {
173→      const aKey = answerPdfKey(universityId, year, subjectKey, examType, ans.questionNumber);
174→      await uploadToR2(aKey, ans.pdfBuffer, "application/pdf");
175→      console.log(`  R2: ${aKey}`);
176→    }
177→  }
178→
179→  console.log(`  DB: university=${universityId}`);
180→
181→  const docPromises: Promise<string>[] = [
182→    createDocument({
183→      universityId,
184→      year,
185→      subject: subjectJa,
186→      examType,
187→      contentType: "problem",
188→      pdfStoragePath: problemOrigKey,
189→    }),
190→  ];
191→  if (answerOrigKey) {
192→    docPromises.push(
193→      createDocument({
194→        universityId,
195→        year,
196→        subject: subjectJa,
197→        examType,
198→        contentType: "answer",
199→        pdfStoragePath: answerOrigKey,
200→      }),
201→    );
202→  }
203→  const [problemDocId, answerDocId] = await Promise.all(docPromises);
204→  console.log(`  DB: problemDoc=${problemDocId}${answerDocId ? `, answerDoc=${answerDocId}` : ""}`);
205→
206→  const boundaryMap = new Map(boundaries.map((b, i) => [i + 1, b]));
207→
208→  for (const split of splitResults) {
209→    const qn = split.questionNumber;
210→    const tags = tagResults.find((t) => t.questionNumber === qn);
211→    const boundary = boundaryMap.get(qn);
212→
213→    const hasAnswer = answerResults.some((a) => a.questionNumber === qn);
214→    const questionId = await createQuestion({
215→      documentId: problemDocId,
216→      questionNumber: qn,
217→      questionLabel: split.label,
218→      startPage: boundary?.startPage ?? 1,
219→      endPage: boundary?.endPage ?? 1,
220→      topicTags: tags?.topicTags ?? [],
221→      splitPdfPath: problemPdfKey(universityId, year, subjectKey, examType, qn),
222→      splitImagePath: problemImageKey(universityId, year, subjectKey, examType, qn),
223→      answerSplitPdfPath: hasAnswer
224→        ? answerPdfKey(universityId, year, subjectKey, examType, qn)
225→        : null,
226→    });
227→    console.log(`  DB: Q${qn} ${split.label} → ${questionId}`);
228→  }
229→
230→  console.log("\n完了");
231→}
232→
233→// CLI引数パース（commander 導入まではシンプルな実装）
234→const args = process.argv.slice(2);
235→function getArg(name: string): string | undefined {
236→  const idx = args.indexOf(`--${name}`);
237→  return idx !== -1 ? args[idx + 1] : undefined;
238→}
239→
240→const problem = getArg("problem");
241→const answer = getArg("answer");
242→const subject = getArg("subject");
243→const university = getArg("university");
244→const year = getArg("year");
245→const examType = getArg("exam-type");
246→
247→if (!problem || !subject || !university || !year || !examType) {
248→  console.error(
249→    "Usage: npx kakomon-generate --problem <pdf> [--answer <pdf>] --subject <subject> --university <name> --year <year> --exam-type <type>",
250→  );
251→  process.exit(1);
252→}
253→
254→main({
255→  problem,
256→  answer: answer || undefined,
257→  subject,
258→  university,
259→  year: Number(year),
260→  examType: examType as CliOptions["examType"],
261→  outDir: getArg("out-dir"),
262→}).catch((err) => {
263→  console.error("エラー:", err);
264→  process.exit(1);
265→});
